package com.videomind.module.auth;import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.Date;import javax.crypto.SecretKey;import org.springframework.stereotype.Service;
@Service public class JwtService{private final AuthProperties p;private final SecretKey key;public JwtService(AuthProperties p){this.p=p;byte[]b=p.getJwtSecret().getBytes(StandardCharsets.UTF_8);if(b.length<32)throw new IllegalStateException("VIDEOMIND_JWT_SECRET 至少 32 字节");key=Keys.hmacShaKeyFor(b);}public String issue(Long id,String username){Instant now=Instant.now();return Jwts.builder().subject(String.valueOf(id)).claim("username",username).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(p.getAccessMinutes()*60))).signWith(key).compact();}public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();}public long expiresIn(){return p.getAccessMinutes()*60;}}
